defmodule Defk.ReportMacros do
  @moduledoc false
  # Kernels generated by a macro, for test/report_test.exs: quoted with
  # `location: :keep`, the fast-path notes go to the lines of this file;
  # quoted plainly, every note is on the line that calls the macro.

  defmacro scaler_keep(name) do
    quote location: :keep do
      defk unquote(name)(a :: [f64], k :: f64) :: [f64] do
        out = alloc(f64, length(a))

        for i <- 0..(length(a) - 1)//1 do
          out[i] = a[i] * k
        end

        out
      end
    end
  end

  defmacro scaler(name) do
    quote do
      defk unquote(name)(a :: [f64], k :: f64) :: [f64] do
        out = alloc(f64, length(a))

        for i <- 0..(length(a) - 1)//1 do
          out[i] = a[i] * k
        end

        out
      end
    end
  end
end
